  ["vacc","Vaccination antitétanique",/tetanos|vaccin|\bvat\b|anatoxine/,"Je ne me souviens pas d'avoir reçu un vaccin contre le tétanos.",1],
  ["allerg","Allergies (antibiotiques, sérum)",/allerg/,"Pas d'allergie connue.",1],
  ["repas","Dernier repas (anesthésie)",/manger|repas|jeun|derniere/,"J'ai mangé ce matin vers 7 heures.",1],
  ["trait","",/traitement|medicament|\bpris\b|automed/,"On m'a donné du paracétamol au carrefour, rien d'autre."],
  ["atcd","",/antecedent|maladie|operat|hospital/,"Pas de maladie connue, pas d'opération."],
  ["tabac","",/tabac|fume|alcool|biere|bois/,"Je bois de la bière de temps en temps, pas ce matin."]
